import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt


def task_func(s1, s2):
    if not isinstance(s1, pd.Series) or not isinstance(s2, pd.Series):
        raise TypeError("s1 and s2 must be pandas Series.")

    values1 = s1.dropna()
    values2 = s2.dropna()

    intersection = pd.Index(values1.unique()).intersection(
        pd.Index(values2.unique())
    )

    plot_data = pd.DataFrame(
        {
            "value": pd.concat([values1, values2], ignore_index=True),
            "series": (["s1"] * len(values1)) + (["s2"] * len(values2)),
        }
    )

    fig, ax = plt.subplots()
    sns.swarmplot(
        data=plot_data,
        x="series",
        y="value",
        ax=ax,
    )

    for value in intersection:
        ax.axhline(value, color="red", linestyle="--")

    return ax, len(intersection)

def check(candidate):
    print(candidate(
        pd.Series([1, 2, 3]),
        pd.Series([2, 3, 4])
    ))

    print(candidate(
        pd.Series([1, 1, 2, 2]),
        pd.Series([3, 3, 4])
    ))

    print(candidate(
        pd.Series([1, None, 2, 2]),
        pd.Series([2, None, 3])
    ))

    print(candidate(
        pd.Series([-2, -1, 0]),
        pd.Series([-1, 0, 1])
    ))

    print(candidate(
        pd.Series([], dtype=float),
        pd.Series([1, 2, 3])
    ))
check(task_func)
